<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/functions.php';
if (current_user($pdo)) redirect('dashboard.php');
if (isset($_GET['reset'])) { unset($_SESSION['application_lookup_user_id'], $_SESSION['correction_user_id']); redirect('application-status.php'); }
$correctionUser = null;
if (!empty($_SESSION['correction_user_id'])) {
    $stmt = $pdo->prepare("SELECT * FROM users WHERE id=? AND role='student' AND status='correction_required' LIMIT 1"); $stmt->execute([(int)$_SESSION['correction_user_id']]); $correctionUser = $stmt->fetch() ?: null;
    if (!$correctionUser) unset($_SESSION['correction_user_id']);
}
$statusUser = null;
if (!$correctionUser && !empty($_SESSION['application_lookup_user_id'])) {
    $stmt = $pdo->prepare("SELECT id, student_id, full_name, program, status, review_note, created_at, reviewed_at FROM users WHERE id=? AND role='student' LIMIT 1"); $stmt->execute([(int)$_SESSION['application_lookup_user_id']]); $statusUser = $stmt->fetch() ?: null;
}
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['check_status'])) {
    verify_csrf();
    $studentId = trim((string)($_POST['student_id'] ?? '')); $password = (string)($_POST['password'] ?? '');
    $stmt = $pdo->prepare("SELECT id, password_hash, role, status FROM users WHERE student_id=? AND role='student' LIMIT 1"); $stmt->execute([$studentId]); $match = $stmt->fetch();
    if (!$match || !password_verify($password, $match['password_hash'])) { set_flash('danger','We could not verify those details. Check the Student ID and password.'); redirect('application-status.php'); }
    unset($_SESSION['application_lookup_user_id'], $_SESSION['correction_user_id']);
    if ($match['status'] === 'correction_required') $_SESSION['correction_user_id'] = (int)$match['id'];
    else $_SESSION['application_lookup_user_id'] = (int)$match['id'];
    redirect('application-status.php');
}
render_header('Application status');
?>
